$file = "src\index_template.html"
$content = Get-Content -Path $file -Encoding UTF8 -Raw

foreach ($country in $potencias.Keys) {
    $data = $potencias[$country]
    $replacement = @"
      potencia_regional: {
        reason: ""$($data.reason)"",
        long_reason: ""$($data.long_reason)"",
        influence: ""$($data.influence)"",
        strengths: ""$($data.strengths)"",
        strategic: ""$($data.strategic)""
      },
      keywords:
"@
    # Regex replacement
    # Look for "CountryName": { ... keywords:
    $pattern = '(?s)("' + $country + '": \{.*?)\s*keywords:'
    $content = [System.Text.RegularExpressions.Regex]::Replace($content, $pattern, "`$1`n" + $replacement)
}

[System.IO.File]::WriteAllText($file, $content, [System.Text.Encoding]::UTF8)
Write-Output "Done!"
